  for el in body:
   tag=etree.QName(el).localname
   if tag=='p':
    text=''.join(el.xpath('.//w:t/text()',namespaces=ns))
    if text.strip(): print(text)
   elif tag=='tbl':
    print('[TABLE]')
    for row in el.xpath('./w:tr',namespaces=ns):
     print(' | '.join(''.join(c.xpath('.//w:t/text()',namespaces=ns)) for c in row.xpath('./w:tc',namespaces=ns)))
