from zipfile import ZipFile
from lxml import etree
p='/work/complaint_preparation.docx'
with ZipFile(p) as z:
 bad=[]
 for n in z.namelist():
  if n.endswith('.xml') or n.endswith('.rels'):
   try: etree.fromstring(z.read(n))
   except Exception as e: bad.append((n,str(e)))
 print('XML parse errors:',bad)
 root=etree.fromstring(z.read('word/document.xml'))
 ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
 for p in root.xpath('.//w:body/w:p',namespaces=ns):
  text=''.join(p.xpath('.//w:t/text()',namespaces=ns))
  if text in ('一、案件与金额梳理','二、诉讼请求与风险分析','三、民事起诉状草稿','四、材料目录与证明目的','民事起诉状','施某诉白某微信购表未交货纠纷','（一）基本关系及时间线'):
   fonts=[]
   for r in p.xpath('.//w:r',namespaces=ns):
    rf=r.find('w:rPr/w:rFonts',ns)
    fonts.append(None if rf is None else tuple(rf.get('{%s}%s'%(ns['w'],x)) for x in ('ascii','hAnsi','eastAsia','cs')))
   print(text, fonts)
 print('docx zip test:',z.testzip())
